public 
enum DataLineError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case DatabaseNotFound(id: String
    )
    case FieldNotFound(id: String
    )
    case RecordNotFound(id: String
    )
    case ReferenceNotFound(id: String
    )
    case BlobNotFound(hash: String
    )
    case ValueKindMismatch(field: String, expected: String
    )
    case UnsupportedFieldKindForValue(field: String, kind: String
    )
    case ReferenceTargetDatabaseMismatch(field: String, expected: String, actual: String
    )
    case ReferenceFieldRetypeNotSupported(field: String
    )
    case Storage(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension DataLineError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDataLineError: FfiConverterRustBuffer {
    typealias SwiftType = DataLineError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DataLineError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .DatabaseNotFound(
            id: try FfiConverterString.read(from: &buf)
            )
        case 2: return .FieldNotFound(
            id: try FfiConverterString.read(from: &buf)
            )
        case 3: return .RecordNotFound(
            id: try FfiConverterString.read(from: &buf)
            )
        case 4: return .ReferenceNotFound(
            id: try FfiConverterString.read(from: &buf)
            )
        case 5: return .BlobNotFound(
            hash: try FfiConverterString.read(from: &buf)
            )
        case 6: return .ValueKindMismatch(
            field: try FfiConverterString.read(from: &buf), 
            expected: try FfiConverterString.read(from: &buf)
            )
        case 7: return .UnsupportedFieldKindForValue(
            field: try FfiConverterString.read(from: &buf), 
            kind: try FfiConverterString.read(from: &buf)
            )
        case 8: return .ReferenceTargetDatabaseMismatch(
            field: try FfiConverterString.read(from: &buf), 
            expected: try FfiConverterString.read(from: &buf), 
            actual: try FfiConverterString.read(from: &buf)
            )
        case 9: return .ReferenceFieldRetypeNotSupported(
            field: try FfiConverterString.read(from: &buf)
            )
        case 10: return .Storage(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DataLineError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .DatabaseNotFound(id):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .FieldNotFound(id):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .RecordNotFound(id):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .ReferenceNotFound(id):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .BlobNotFound(hash):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(hash, into: &buf)
            
        
        case let .ValueKindMismatch(field,expected):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(field, into: &buf)
            FfiConverterString.write(expected, into: &buf)
            
        
        case let .UnsupportedFieldKindForValue(field,kind):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(field, into: &buf)
            FfiConverterString.write(kind, into: &buf)
            
        
        case let .ReferenceTargetDatabaseMismatch(field,expected,actual):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(field, into: &buf)
            FfiConverterString.write(expected, into: &buf)
            FfiConverterString.write(actual, into: &buf)
            
        
        case let .ReferenceFieldRetypeNotSupported(field):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(field, into: &buf)
            
        
        case let .Storage(message):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


