public enum FieldKind: Equatable, Hashable {
    
    case text
    case number
    case boolean
    case selection(multi: Bool, options: [SelectionOption]
    )
    case date
    /**
     * `target_database` is a database id string. `paired_field` is ignored
     * on the way in — `dataline-core::SchemaRegistry::add_field` always
     * establishes pairing itself, the same way it ignores a caller-supplied
     * value for this today (see that method's tests).
     */
    case reference(targetDatabase: String, pairedField: String?
    )
    case blob





}

#if compiler(>=6)
extension FieldKind: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFieldKind: FfiConverterRustBuffer {
    typealias SwiftType = FieldKind

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FieldKind {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .text
        
        case 2: return .number
        
        case 3: return .boolean
        
        case 4: return .selection(multi: try FfiConverterBool.read(from: &buf), options: try FfiConverterSequenceTypeSelectionOption.read(from: &buf)
        )
        
        case 5: return .date
        
        case 6: return .reference(targetDatabase: try FfiConverterString.read(from: &buf), pairedField: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 7: return .blob
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FieldKind, into buf: inout [UInt8]) {
        switch value {
        
        
        case .text:
            writeInt(&buf, Int32(1))
        
        
        case .number:
            writeInt(&buf, Int32(2))
        
        
        case .boolean:
            writeInt(&buf, Int32(3))
        
        
        case let .selection(multi,options):
            writeInt(&buf, Int32(4))
            FfiConverterBool.write(multi, into: &buf)
            FfiConverterSequenceTypeSelectionOption.write(options, into: &buf)
            
        
        case .date:
            writeInt(&buf, Int32(5))
        
        
        case let .reference(targetDatabase,pairedField):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(targetDatabase, into: &buf)
            FfiConverterOptionString.write(pairedField, into: &buf)
            
        
        case .blob:
            writeInt(&buf, Int32(7))
        
        }
    }
}


